import { test, describe } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";

import * as m from "../../src/ratings/notch.mjs";
import { RATING_SCALE, notchChange, notchCalculator } from "../../src/ratings/notch.mjs";

const here = dirname(fileURLToPath(import.meta.url));
const repoRoot = join(here, "..", "..");

const EXPECTED_SCALE = [
  "AAA", "AA+", "AA", "AA-", "A+", "A", "A-",
  "BBB+", "BBB", "BBB-", "BB+", "BB", "BB-",
  "B+", "B", "B-", "CCC+", "CCC", "CCC-",
];

// Table B: invalid values (JS literals; look-alikes written as escapes).
const INVALID = [
  ["empty", ""],
  ["blank (3 spaces)", "   "],
  ["blank (1 space)", " "],
  ["internal whitespace BBB +", "BBB +"],
  ["internal whitespace B BB+", "B BB+"],
  ["internal whitespace BB B", "BB B"],
  ["AAA+", "AAA+"],
  ["CCC--", "CCC--"],
  ["BBB++", "BBB++"],
  ["D", "D"],
  ["SD", "SD"],
  ["NR", "NR"],
  ["Baa1", "Baa1"],
  ["Unicode minus", "BBB−"],
  ["full-width BBB", "ＢＢＢ"],
  ["zero-width space", "​BBB"],
  ["null", null],
  ["undefined", undefined],
  ["number 7", 7],
  ["object {}", {}],
  ["array [BBB]", ["BBB"]],
  ["String object", new String("BBB")],
];

describe("AC-1: RATING_SCALE", () => {
  test("deep-equals the 19 ratings, best first", () => {
    assert.deepStrictEqual(RATING_SCALE, EXPECTED_SCALE);
  });

  test("uses ASCII plus and hyphen-minus only", () => {
    for (const r of RATING_SCALE) assert.match(r, /^[A-Z+\-]+$/);
  });

  test("length is 19", () => {
    assert.equal(RATING_SCALE.length, 19);
  });

  test("is frozen and cannot be mutated", () => {
    assert.equal(Object.isFrozen(RATING_SCALE), true);
    assert.throws(() => RATING_SCALE.push("D"), TypeError);
    assert.equal(RATING_SCALE.length, 19);
  });
});

describe("AC-2: notchChange", () => {
  const cases = [
    ["BBB+", "BB+", 3],
    ["BBB+", "BBB-", 2],
    ["BBB", "BBB-", 1],
    ["AAA", "CCC-", 18],
    ["BB+", "BBB+", -3],
    ["BBB-", "BBB", -1],
    ["CCC-", "AAA", -18],
    ["A", "A", 0],
    ["AAA", "AAA", 0],
    ["CCC-", "CCC-", 0],
    ["BBB", "BBB+", -1],
    ["BBB", "B", 6],
  ];
  for (const [p, c, n] of cases) {
    test(`${p} -> ${c} is ${n}`, () => {
      assert.equal(notchChange(p, c), n);
    });
  }

  test("unchanged is +0, never -0", () => {
    assert.equal(Object.is(notchChange("A", "A"), 0), true);
    assert.equal(Object.is(notchChange("CCC-", "CCC-"), 0), true);
  });

  test("every result is an integer in -18..18", () => {
    for (const p of RATING_SCALE) {
      for (const c of RATING_SCALE) {
        const r = notchChange(p, c);
        assert.ok(Number.isInteger(r));
        assert.ok(r >= -18 && r <= 18);
      }
    }
  });
});

describe("AC-3: normalisation of case and surrounding whitespace", () => {
  test("lower case", () => {
    assert.equal(notchChange("bbb+", "BB+"), 3);
  });
  test("spaces and mixed case", () => {
    assert.equal(notchChange("  BBB+ ", "bb+"), 3);
  });
  test("tab and newline", () => {
    assert.equal(notchChange("\tBbb+\n", "BB+"), 3);
  });
  test("NBSP", () => {
    assert.equal(notchChange(" BBB+ ", "BB+"), 3);
  });
  test("em space and BOM", () => {
    assert.equal(notchChange(" bbb-", "﻿BBB"), -1);
  });
  test("notchCalculator normalises too", () => {
    assert.deepStrictEqual(notchCalculator(" bbb+ ", "bb+"), {
      notches: 3,
      direction: "downgrade",
      wl: 2,
    });
    assert.deepStrictEqual(notchCalculator(" BBB+ ", "﻿bb+"), {
      notches: 3,
      direction: "downgrade",
      wl: 2,
    });
  });
  test("matching is exact, not by prefix", () => {
    assert.equal(notchChange("BBB", "B"), 6);
    assert.equal(notchChange("B", "BB"), -3);
    assert.equal(notchChange("BB", "BBB"), -3);
  });
});

describe("AC-4: invalid input throws RangeError", () => {
  for (const [label, bad] of INVALID) {
    test(`notchChange: ${label} as previous`, () => {
      assert.throws(() => notchChange(bad, "BBB"), RangeError);
    });
    test(`notchChange: ${label} as current`, () => {
      assert.throws(() => notchChange("BBB", bad), RangeError);
    });
    test(`notchCalculator: ${label} as previous`, () => {
      assert.throws(() => notchCalculator(bad, "BBB"), RangeError);
    });
    test(`notchCalculator: ${label} as current`, () => {
      assert.throws(() => notchCalculator("BBB", bad), RangeError);
    });
  }

  test("missing arguments throw RangeError", () => {
    assert.throws(() => notchChange("BBB"), RangeError);
    assert.throws(() => notchChange(), RangeError);
    assert.throws(() => notchCalculator("BBB"), RangeError);
    assert.throws(() => notchCalculator(), RangeError);
  });

  test("both invalid throws RangeError", () => {
    assert.throws(() => notchChange("XYZ", "QQQ"), RangeError);
    assert.throws(() => notchCalculator("XYZ", "QQQ"), RangeError);
  });

  test("the error is never a TypeError", () => {
    for (const [, bad] of INVALID) {
      try {
        notchChange(bad, "BBB");
        assert.fail("expected throw");
      } catch (e) {
        assert.ok(e instanceof RangeError);
        assert.ok(!(e instanceof TypeError));
      }
    }
  });

  test("previous is checked first", () => {
    assert.throws(() => notchChange("XYZ", "QQQ"), (e) => {
      return e instanceof RangeError && e.message.includes("XYZ") && !e.message.includes("QQQ");
    });
  });
});

describe("AC-5: notchCalculator on the table A pairs", () => {
  test("C2: BBB+ -> BB+ is 3 notches, WL 2 (overrides POC example)", () => {
    assert.deepStrictEqual(notchCalculator("BBB+", "BB+"), { notches: 3, direction: "downgrade", wl: 2 });
  });
  test("C2: BBB+ -> BBB- is 2 notches, WL 1", () => {
    assert.deepStrictEqual(notchCalculator("BBB+", "BBB-"), { notches: 2, direction: "downgrade", wl: 1 });
  });
  test("C6: BBB+ -> BBB is 1 notch, WL 0", () => {
    assert.deepStrictEqual(notchCalculator("BBB+", "BBB"), { notches: 1, direction: "downgrade", wl: 0 });
  });
  test("C6: BBB -> BBB- is 1 notch, WL 0", () => {
    assert.deepStrictEqual(notchCalculator("BBB", "BBB-"), { notches: 1, direction: "downgrade", wl: 0 });
  });
  test("scale end: AAA -> CCC- is 18 notches, WL 2", () => {
    assert.deepStrictEqual(notchCalculator("AAA", "CCC-"), { notches: 18, direction: "downgrade", wl: 2 });
  });
  test("C3, C5: BB+ -> BBB+ is an upgrade of 3, WL 0", () => {
    assert.deepStrictEqual(notchCalculator("BB+", "BBB+"), { notches: -3, direction: "upgrade", wl: 0 });
  });
  test("C3: BBB -> BBB+ upgrade", () => {
    assert.deepStrictEqual(notchCalculator("BBB", "BBB+"), { notches: -1, direction: "upgrade", wl: 0 });
  });
  test("C3: BBB- -> BBB upgrade", () => {
    assert.deepStrictEqual(notchCalculator("BBB-", "BBB"), { notches: -1, direction: "upgrade", wl: 0 });
  });
  test("scale end: CCC- -> AAA is -18, WL 0", () => {
    assert.deepStrictEqual(notchCalculator("CCC-", "AAA"), { notches: -18, direction: "upgrade", wl: 0 });
  });
  test("C3: A -> A is unchanged", () => {
    const r = notchCalculator("A", "A");
    assert.deepStrictEqual(r, { notches: 0, direction: "unchanged", wl: 0 });
    assert.equal(Object.is(r.notches, 0), true);
  });
  test("scale end: CCC- -> CCC- is unchanged", () => {
    assert.deepStrictEqual(notchCalculator("CCC-", "CCC-"), { notches: 0, direction: "unchanged", wl: 0 });
  });
  test("exact match: BBB -> B is 6 notches, WL 2", () => {
    assert.deepStrictEqual(notchCalculator("BBB", "B"), { notches: 6, direction: "downgrade", wl: 2 });
  });
  test("4 or more notches still give WL 2", () => {
    assert.equal(notchCalculator("BBB+", "BB").wl, 2);
  });
  test("result is a plain object with exactly three keys", () => {
    const r = notchCalculator("BBB+", "BB+");
    assert.equal(Object.getPrototypeOf(r), Object.prototype);
    assert.deepStrictEqual(Object.keys(r).sort(), ["direction", "notches", "wl"]);
  });
});

describe("AC-6: all 361 pairs", () => {
  test("notches, direction and wl follow the rules", () => {
    let count = 0;
    for (const p of RATING_SCALE) {
      for (const c of RATING_SCALE) {
        count++;
        const r = notchCalculator(p, c);
        const n = notchChange(p, c);
        const label = `${p} -> ${c}`;
        assert.equal(r.notches, n, label);
        const dir = n > 0 ? "downgrade" : n < 0 ? "upgrade" : "unchanged";
        assert.equal(r.direction, dir, label);
        const wl = n >= 3 ? 2 : n === 2 ? 1 : 0;
        assert.equal(r.wl, wl, label);
        assert.ok(r.wl !== 3 && r.wl !== 4, label);
      }
    }
    assert.equal(count, 361);
  });
});

describe("AC-8: 1-notch downgrade", () => {
  test("C6: BBB+ -> BBB has wl 0", () => {
    const r = notchCalculator("BBB+", "BBB");
    assert.equal(r.wl, 0);
    assert.equal(r.notches, 1);
    assert.equal(r.direction, "downgrade");
  });
});

describe("AC-9: arity and statelessness", () => {
  test("both functions take exactly two parameters", () => {
    assert.equal(notchChange.length, 2);
    assert.equal(notchCalculator.length, 2);
  });
  test("no state between calls", () => {
    assert.equal(notchCalculator("BBB+", "BBB-").wl, 1);
    assert.equal(notchCalculator("BBB+", "BB+").wl, 2);
    assert.equal(notchCalculator("BBB+", "BBB-").wl, 1);
  });
  test("each call returns a new object that is deep-equal", () => {
    const a = notchCalculator("BBB+", "BB+");
    const b = notchCalculator("BBB+", "BB+");
    assert.notEqual(a, b);
    assert.deepStrictEqual(a, b);
  });
  test("the returned object is not frozen and mutation does not leak", () => {
    const a = notchCalculator("BBB+", "BB+");
    assert.equal(Object.isFrozen(a), false);
    a.wl = 9;
    assert.equal(a.wl, 9);
    assert.equal(notchCalculator("BBB+", "BB+").wl, 2);
  });
});

describe("AC-11: module shape", () => {
  test("exports RATING_SCALE, notchChange, notchCalculator only; no default", () => {
    assert.ok("RATING_SCALE" in m);
    assert.ok("notchChange" in m);
    assert.ok("notchCalculator" in m);
    assert.equal("externalRatingChangeWl" in m, false);
    assert.equal("default" in m, false);
    assert.deepStrictEqual(Object.keys(m).sort(), ["RATING_SCALE", "notchCalculator", "notchChange"]);
  });

  test("source has no imports, require, console or process", () => {
    const src = readFileSync(join(repoRoot, "src", "ratings", "notch.mjs"), "utf8");
    assert.doesNotMatch(src, /^\s*import\s/m);
    assert.doesNotMatch(src, /import\s*\(/);
    assert.doesNotMatch(src, /require\s*\(/);
    assert.doesNotMatch(src, /console\./);
    assert.doesNotMatch(src, /process\./);
  });

  test("functions are synchronous", () => {
    assert.equal(typeof notchChange("A", "A"), "number");
    assert.ok(!(notchCalculator("A", "A") instanceof Promise));
  });

  test("package.json is unchanged: no dependencies, test script is node --test", () => {
    const pkg = JSON.parse(readFileSync(join(repoRoot, "package.json"), "utf8"));
    assert.equal("dependencies" in pkg, false);
    assert.equal("devDependencies" in pkg, false);
    assert.equal(pkg.scripts.test, "node --test");
  });
});

// Rating scale and notch calculator (REQ-06-02).
// Pure functions: no imports, no I/O.

/** Long-term rating scale (C1), best first. Index 0 = AAA, index 18 = CCC-. */
export const RATING_SCALE = Object.freeze([
  "AAA", "AA+", "AA", "AA-", "A+", "A", "A-",
  "BBB+", "BBB", "BBB-", "BB+", "BB", "BB-",
  "B+", "B", "B-", "CCC+", "CCC", "CCC-",
]);

/**
 * Validate one rating argument and return its index on RATING_SCALE.
 * Non-strings are rejected before trim(); trim() removes surrounding
 * whitespace (incl. NBSP, em space, BOM); toUpperCase() is locale-independent.
 * Throws RangeError naming the argument and the offending value.
 */
function indexOfRating(name, value) {
  if (typeof value !== "string") {
    throw new RangeError(`${name}: expected a rating string, got ${describe(value)}`);
  }
  const index = RATING_SCALE.indexOf(value.trim().toUpperCase());
  if (index === -1) {
    throw new RangeError(`${name}: unknown rating ${JSON.stringify(value)}`);
  }
  return index;
}

function describe(value) {
  if (value === null) return "null";
  if (Array.isArray(value)) return "array";
  return typeof value;
}

/**
 * Signed notch change: index(current) - index(previous).
 * Positive = downgrade, negative = upgrade, +0 = unchanged.
 */
export function notchChange(previous, current) {
  const from = indexOfRating("previous", previous);
  const to = indexOfRating("current", current);
  return to - from + 0; // "+ 0" turns -0 into +0
}

/** Notch change, direction and resulting WL (0, 1 or 2) for a rating move. */
export function notchCalculator(previous, current) {
  const notches = notchChange(previous, current);
  const direction = notches > 0 ? "downgrade" : notches < 0 ? "upgrade" : "unchanged";
  const wl = notches >= 3 ? 2 : notches === 2 ? 1 : 0;
  return { notches, direction, wl };
}

