const SRC = fileURLToPath(new URL("../../../src/ratings/notch.mjs", import.meta.url));

const EXPECTED_SCALE = [
  "AAA", "AA+", "AA", "AA-", "A+", "A", "A-",
  "BBB+", "BBB", "BBB-", "BB+", "BB", "BB-",
  "B+", "B", "B-", "CCC+", "CCC", "CCC-",
];

// Table A: valid pairs [previous, current, notches, direction, wl]
