  ["BBB+", "BB+", 3, "downgrade", 2],
  ["BBB+", "BBB-", 2, "downgrade", 1],
  ["BBB+", "BBB", 1, "downgrade", 0],
  ["BBB", "BBB-", 1, "downgrade", 0],
  ["AAA", "CCC-", 18, "downgrade", 2],
  ["BB+", "BBB+", -3, "upgrade", 0],
  ["BBB", "BBB+", -1, "upgrade", 0],
  ["BBB-", "BBB", -1, "upgrade", 0],
  ["CCC-", "AAA", -18, "upgrade", 0],
  ["A", "A", 0, "unchanged", 0],
  ["CCC-", "CCC-", 0, "unchanged", 0],
  ["BBB", "B", 6, "downgrade", 2],
];

// Table B: invalid values (thunks are not needed; literals only)
const INVALID = [
  "", "   ", " ",
  "BBB +", "B BB+", "BB B",
  "AAA+", "CCC--", "BBB++", "D", "SD", "NR", "Baa1",
  "BBB−", // Unicode minus
  "ＢＢＢ", // full-width BBB
  "​BBB", // zero-width space
  null, undefined,
  7, {}, ["BBB"], new String("BBB"),
];

const label = (v) => {
  if (typeof v === "string") return JSON.stringify(v);
  if (v instanceof String) return "new String(\"BBB\")";
  if (Array.isArray(v)) return "[\"BBB\"]";
  if (typeof v === "object" && v !== null) return "{}";
  return String(v);
};

// ---------------------------------------------------------------- AC-1
test("AC-1: RATING_SCALE deep-equals the 19 C1 ratings with ASCII + and -", () => {
  assert.deepStrictEqual([...RATING_SCALE], EXPECTED_SCALE);
  for (const r of RATING_SCALE) {
    assert.match(r, /^[A-Z+\-]+$/, `non-ASCII character in ${r}`);
  }
});

test("AC-1: RATING_SCALE has length 19 and is frozen", () => {
  assert.equal(RATING_SCALE.length, 19);
  assert.equal(Object.isFrozen(RATING_SCALE), true);
});

test("AC-1: RATING_SCALE.push throws TypeError and length stays 19", () => {
  assert.throws(() => RATING_SCALE.push("D"), TypeError);
  assert.equal(RATING_SCALE.length, 19);
  assert.throws(() => { "use strict"; RATING_SCALE[0] = "X"; }, TypeError);
  assert.equal(RATING_SCALE[0], "AAA");
});

// ---------------------------------------------------------------- AC-2
test("AC-2: notchChange returns index(current) - index(previous) for spec pairs", () => {
  assert.equal(notchChange("BBB+", "BB+"), 3);
  assert.equal(notchChange("BBB+", "BBB-"), 2);
  assert.equal(notchChange("BBB", "BBB-"), 1);
  assert.equal(notchChange("AAA", "CCC-"), 18);
  assert.equal(notchChange("BB+", "BBB+"), -3);
  assert.equal(notchChange("BBB-", "BBB"), -1);
  assert.equal(notchChange("CCC-", "AAA"), -18);
  assert.equal(notchChange("A", "A"), 0);
});

test("AC-2: unchanged is +0, never -0", () => {
  assert.equal(Object.is(notchChange("A", "A"), 0), true);
  assert.equal(Object.is(notchChange("CCC-", "CCC-"), 0), true);
  assert.equal(Object.is(notchChange("AAA", "AAA"), 0), true);
});

test("AC-2: every result over all 361 pairs is an integer in -18..18 and matches the index difference", () => {
  for (let i = 0; i < 19; i++) {
    for (let j = 0; j < 19; j++) {
      const r = notchChange(RATING_SCALE[i], RATING_SCALE[j]);
      assert.equal(Number.isInteger(r), true);
      assert.ok(r >= -18 && r <= 18);
      assert.equal(r, j - i);
      assert.equal(Object.is(r, -0), false);
    }
  }
});

// ---------------------------------------------------------------- AC-3
test("AC-3: notchChange accepts case and surrounding whitespace variants", () => {
  assert.equal(notchChange("bbb+", "BB+"), 3);
  assert.equal(notchChange("  BBB+ ", "bb+"), 3);
  assert.equal(notchChange("\tBbb+\n", "BB+"), 3);
});

test("AC-3: notchChange accepts NBSP, em space and BOM padding", () => {
  assert.equal(notchChange(" BBB+ ", "BB+"), 3); // NBSP
  assert.equal(notchChange(" bbb-", "﻿BBB"), -1); // em space, BOM
});

test("AC-3: notchCalculator(' bbb+ ','bb+') deep-equals the canonical result", () => {
  assert.deepStrictEqual(notchCalculator(" bbb+ ", "bb+"), { notches: 3, direction: "downgrade", wl: 2 });
  assert.deepStrictEqual(
    notchCalculator(" bbb+ ", "﻿bb+"),
    { notches: 3, direction: "downgrade", wl: 2 },
  );
});

test("AC-3: normalised input gives the same result as canonical input for every scale entry", () => {
  for (const p of RATING_SCALE) {
    for (const c of RATING_SCALE) {
