// T-02 QA: integration tests for src/indicators/countryRating.mjs through its public exports.
import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { spawnSync } from "node:child_process";
import * as m from "../../../src/indicators/countryRating.mjs";
import { RATING_SCALE, notchChange, notchCalculator } from "../../../src/ratings/notch.mjs";

const { countryRatingChangeWl } = m;

const ROOT = fileURLToPath(new URL("../../../", import.meta.url));
const SRC_URL = new URL("../../../src/indicators/countryRating.mjs", import.meta.url);
const SRC = readFileSync(SRC_URL, "utf8");

// T-01 table B: invalid values.
const INVALID = [
  "", "   ", " ",
  "BBB +", "B BB+", "BB B",
  "AAA+", "CCC--", "BBB++", "D", "SD", "NR", "Baa1",
  "BBB−", // Unicode minus
  "ＢＢＢ", // full-width BBB
  "​BBB", // zero-width space
  null, undefined,
  7, {}, ["BBB"], new String("BBB"),
];

const label = (v) => {
  if (typeof v === "string") return JSON.stringify(v);
  if (v instanceof String) return 'new String("BBB")';
  if (Array.isArray(v)) return '["BBB"]';
  if (typeof v === "object" && v !== null) return "{}";
  return String(v);
};

const expectedWl = (n) => (n >= 2 ? 2 : n === 1 ? 1 : 0);

// ---------------------------------------------------------------- AC-7
const AC7 = [
  ["BBB+", "BBB", 1],
  ["BBB+", "BBB-", 2],
  ["BBB+", "BB+", 2],
  ["AAA", "CCC-", 2],
  ["BBB", "BBB+", 0],
  ["CCC-", "AAA", 0],
  ["A", "A", 0],
  // scale ends and thresholds
  ["CCC-", "CCC-", 0],
  ["AAA", "AAA", 0],
  ["CCC+", "CCC-", 2],
  ["CCC", "CCC-", 1],
];
for (const [p, c, wl] of AC7) {
  test(`AC-7: (${p}, ${c}) -> WL ${wl}`, () => {
    const r = countryRatingChangeWl(p, c);
    assert.equal(typeof r, "number");
    assert.equal(r, wl);
    assert.ok([0, 1, 2].includes(r));
  });
}

test("AC-7: threshold boundary -1/0/+1/+2/+3/-18 notches map to 0/0/1/2/2/0", () => {
  assert.equal(countryRatingChangeWl("BBB", "BBB+"), 0); // -1
  assert.equal(countryRatingChangeWl("BBB", "BBB"), 0); // 0
  assert.equal(countryRatingChangeWl("BBB", "BBB-"), 1); // +1
  assert.equal(countryRatingChangeWl("BBB", "BB+"), 2); // +2
  assert.equal(countryRatingChangeWl("BBB", "BB"), 2); // +3
  assert.equal(countryRatingChangeWl("CCC-", "AAA"), 0); // -18
});

// ---------------------------------------------------------------- AC-7 / AC-10 all pairs
test("AC-7 / AC-10: all 361 pairs follow notchChange (>=2 -> 2, 1 -> 1, else 0), integer in [0, 2]", () => {
  assert.equal(RATING_SCALE.length, 19);
  let count = 0;
  for (const p of RATING_SCALE) {
    for (const c of RATING_SCALE) {
      const n = notchChange(p, c);
      const r = countryRatingChangeWl(p, c);
      assert.equal(r, expectedWl(n), `(${p}, ${c}) notches ${n}`);
      assert.ok(Number.isInteger(r), `(${p}, ${c}) not an integer`);
      assert.ok(r >= 0 && r <= 2, `(${p}, ${c}) out of range`);
      assert.ok(!Object.is(r, -0), `(${p}, ${c}) is -0`);
      count++;
    }
  }
  assert.equal(count, 361);
});

test("AC-7: WL 3 and WL 4 are never returned over all pairs", () => {
  const seen = new Set();
  for (const p of RATING_SCALE) for (const c of RATING_SCALE) seen.add(countryRatingChangeWl(p, c));
  assert.deepEqual([...seen].sort(), [0, 1, 2]);
});

// ---------------------------------------------------------------- AC-3
test("AC-3: ' bbb+' -> 'BBB\\n' is WL 1 (case and whitespace normalised)", () => {
  assert.equal(countryRatingChangeWl(" bbb+", "BBB\n"), 1);
});

test("AC-3: ' bbb+' -> BOM + 'bb+' is WL 2 (BOM is trimmed)", () => {
  assert.equal(countryRatingChangeWl(" bbb+", "﻿bb+"), 2);
});

test("AC-3: tabs, NBSP and em space around a rating are accepted", () => {
  assert.equal(countryRatingChangeWl("\tBbb+\n", " BBB- "), 2);
});

// ---------------------------------------------------------------- AC-4
for (const bad of INVALID) {
  test(`AC-4: ${label(bad)} as previous (current "BBB") throws RangeError`, () => {
    assert.throws(() => countryRatingChangeWl(bad, "BBB"), RangeError);
  });
  test(`AC-4: ${label(bad)} as current (previous "BBB") throws RangeError`, () => {
    assert.throws(() => countryRatingChangeWl("BBB", bad), RangeError);
  });
}

test("AC-4: the argument left out throws RangeError (previous, current, both)", () => {
  assert.throws(() => countryRatingChangeWl(), RangeError);
  assert.throws(() => countryRatingChangeWl("BBB"), RangeError);
  assert.throws(() => countryRatingChangeWl(undefined, "BBB"), RangeError);
});

test("AC-4: both invalid ('XYZ', 'QQQ') throws RangeError", () => {
  assert.throws(() => countryRatingChangeWl("XYZ", "QQQ"), RangeError);
});

test("AC-4: non-strings throw RangeError, not TypeError", () => {
  for (const bad of [null, new String("BBB"), 7, {}, ["BBB"]]) {
    for (const args of [[bad, "BBB"], ["BBB", bad]]) {
      let err;
      try {
        countryRatingChangeWl(...args);
      } catch (e) {
        err = e;
      }
      assert.ok(err instanceof RangeError, `${label(bad)} did not throw RangeError`);
      assert.ok(!(err instanceof TypeError), `${label(bad)} threw TypeError`);
    }
  }
});

test("AC-4: errors are thrown synchronously, not returned as a Promise or fallback value", () => {
  let returned = "not-set";
  assert.throws(() => {
    returned = countryRatingChangeWl("XYZ", "BBB");
  }, RangeError);
  assert.equal(returned, "not-set");
});

test("AC-4: validation comes from notchChange (same error type for the same input)", () => {
  for (const bad of INVALID) {
    let a;
    let b;
    try { notchChange(bad, "BBB"); } catch (e) { a = e; }
    try { countryRatingChangeWl(bad, "BBB"); } catch (e) { b = e; }
    assert.ok(a instanceof RangeError);
    assert.ok(b instanceof RangeError);
  }
});

// ---------------------------------------------------------------- AC-8
test("AC-8 / C6: BBB+ -> BBB is calculator wl 0 but Indicator 12 WL 1 (the difference is intended)", () => {
  assert.equal(notchCalculator("BBB+", "BBB").wl, 0);
  assert.equal(countryRatingChangeWl("BBB+", "BBB"), 1);
});

// ---------------------------------------------------------------- AC-9
test("AC-9 / C7: countryRatingChangeWl takes exactly two parameters", () => {
  assert.equal(countryRatingChangeWl.length, 2);
});

test("AC-9 / C7: no stored state - BBB+/BBB, then BBB+/BB+, then BBB+/BBB again gives 1, 2, 1", () => {
  assert.equal(countryRatingChangeWl("BBB+", "BBB"), 1);
  assert.equal(countryRatingChangeWl("BBB+", "BB+"), 2);
  assert.equal(countryRatingChangeWl("BBB+", "BBB"), 1);
});

test("AC-9 / C7: a failed call does not poison later calls", () => {
  assert.throws(() => countryRatingChangeWl("XYZ", "BBB"), RangeError);
  assert.equal(countryRatingChangeWl("BBB+", "BBB-"), 2);
});

test("AC-9 / C7: no override - a third argument does not change the result", () => {
  assert.equal(countryRatingChangeWl("BBB+", "BBB", 2), 1);
  assert.equal(countryRatingChangeWl("BBB+", "BBB", { wl: 0 }), 1);
  assert.equal(countryRatingChangeWl("BBB+", "BB+", 0), 2);
});

// ---------------------------------------------------------------- AC-10
test("AC-10: the source has exactly one static import, notchChange from ../ratings/notch.mjs", () => {
  const imports = [...SRC.matchAll(/^\s*import\b[^;]*;?/gm)].map((x) => x[0].trim());
  assert.equal(imports.length, 1, imports.join("\n"));
  assert.match(imports[0], /^import\s*\{\s*notchChange\s*\}\s*from\s*["']\.\.\/ratings\/notch\.mjs["']\s*;?$/);
  assert.equal([...SRC.matchAll(/\bfrom\s*["']/g)].length, 1);
});

test("AC-10: the source has no quoted literal of the rating list ('BBB+' / 'CCC-')", () => {
  for (const lit of ['"BBB+"', "'BBB+'", '"CCC-"', "'CCC-'", "`BBB+`", "`CCC-`"]) {
    assert.ok(!SRC.includes(lit), `source contains ${lit}`);
  }
  assert.ok(!/\bRATING_SCALE\b/.test(SRC.replace(/\/\/.*$/gm, "")), "source defines or uses its own scale");
});

test("AC-10: the source uses notchChange for the calculation", () => {
  assert.match(SRC, /notchChange\s*\(/);
});

// ---------------------------------------------------------------- AC-11
test("AC-11: exports countryRatingChangeWl only (no externalRatingChangeWl, no default)", () => {
  assert.equal(typeof m.countryRatingChangeWl, "function");
  assert.ok(!("externalRatingChangeWl" in m));
  assert.ok(!("default" in m));
  assert.deepEqual(Object.keys(m), ["countryRatingChangeWl"]);
});

test("AC-11: the source has no externalRatingChangeWl, node:, fs, http, require(, import(, console., process.", () => {
  assert.ok(!SRC.includes("externalRatingChangeWl"));
  assert.ok(!SRC.includes("node:"));
  assert.ok(!/["']fs["']|["']http["']|\bfs\./.test(SRC));
  assert.ok(!/\bfrom\s*["'](?:fs|http|https)["']/.test(SRC));
  assert.ok(!SRC.includes("require("));
  assert.ok(!SRC.includes("import("));
  assert.ok(!SRC.includes("console."));
  assert.ok(!SRC.includes("process."));
});

test("AC-11: countryRatingChangeWl is synchronous and returns a number, not a Promise", () => {
  const r = countryRatingChangeWl("A", "A");
  assert.equal(typeof r, "number");
  assert.ok(!(r instanceof Promise));
  assert.equal(typeof r?.then, "undefined");
  assert.notEqual(countryRatingChangeWl.constructor.name, "AsyncFunction");
});

test("AC-11: package.json has no dependencies or devDependencies", () => {
  const pkg = JSON.parse(readFileSync(new URL("../../../package.json", import.meta.url), "utf8"));
  assert.ok(!("dependencies" in pkg));
  assert.ok(!("devDependencies" in pkg));
  assert.equal(pkg.scripts.test, "node --test");
});

test("AC-11: importing the module has no side effects on stdout/stderr", () => {
  const res = spawnSync(
    process.execPath,
    ["--input-type=module", "-e", `import ${JSON.stringify(SRC_URL.href)};`],
    { encoding: "utf8" },
  );
  assert.equal(res.status, 0, res.stderr);
  assert.equal(res.stdout, "");
  assert.equal(res.stderr, "");
});

// ---------------------------------------------------------------- AC-12
test("AC-12: `node --test` from the repository root exits 0 and runs both unit test files", (t) => {
  if (process.env.QA_T02_NESTED === "1") {
    t.skip("nested run: avoid recursion");
    return;
  }
  const res = spawnSync(process.execPath, ["--test", "--test-reporter=spec"], {
    cwd: ROOT,
    encoding: "utf8",
    env: { ...process.env, QA_T02_NESTED: "1" },
  });
  const out = res.stdout + res.stderr;
  assert.equal(res.status, 0, out);
  // Names taken from test/ratings/notch.test.mjs and test/indicators/countryRating.test.mjs
  assert.match(out, /AC-1: RATING_SCALE/);
  assert.match(out, /AC-2: notchChange/);
  assert.match(out, /AC-7: WL from the notch change/);
  assert.match(out, /AC-8: intended difference to notchCalculator/);
  assert.match(out, /AC-10 \/ AC-11: source and module shape/);
});

test("AC-12: the unit test files exist and use node:test and node:assert/strict", () => {
  for (const f of ["test/ratings/notch.test.mjs", "test/indicators/countryRating.test.mjs"]) {
    const text = readFileSync(new URL(`../../../${f}`, import.meta.url), "utf8");
    assert.match(text, /from\s*["']node:test["']/, f);
    assert.match(text, /from\s*["']node:assert\/strict["']/, f);
  }
});

