+// Indicator 12: country rating change WL (REQ-03-12).
+// Pure function: no I/O. Built on notchChange; validation comes from there.
+import { notchChange } from "../ratings/notch.mjs";
+
+/**
+ * Watchlist level (0, 1 or 2) for a change of the country rating.
+ * One notch downgrade -> 1, two or more -> 2, unchanged or upgrade -> 0 (C3).
+ * Intentionally differs from notchCalculator().wl for a 1-notch downgrade (C6).
+ * Throws RangeError (from notchChange) for an invalid rating.
+ */
+export function countryRatingChangeWl(previous, current) {
+  const notches = notchChange(previous, current);
+  if (notches >= 2) return 2;
+  if (notches === 1) return 1;
+  return 0;
+}
