+const PACKAGE_URL = new URL("../../package.json", import.meta.url);
+
+// Table B of T-01: invalid values (look-alikes written as escapes).
+const INVALID = [
+  ["empty", ""],
+  ["blank (3 spaces)", "   "],
+  ["blank (1 space)", " "],
+  ["internal whitespace BBB +", "BBB +"],
