+  ["full-width BBB", "ＢＢＢ"],
+  ["zero-width space", "​BBB"],
+  ["null", null],
+  ["undefined", undefined],
+  ["number 7", 7],
+  ["object {}", {}],
+  ["array [BBB]", ["BBB"]],
+  ["String object", new String("BBB")],
