+
+describe("AC-7: WL from the notch change", () => {
+  const table = [
+    ["BBB+", "BBB", 1],
+    ["BBB+", "BBB-", 2],
+    ["BBB+", "BB+", 2],
+    ["AAA", "CCC-", 2],
+    ["CCC", "CCC-", 1],
+    ["CCC+", "CCC-", 2],
+    ["BBB", "BBB+", 0],
+    ["CCC-", "AAA", 0],
+    ["A", "A", 0],
+    ["AAA", "AAA", 0],
+    ["CCC-", "CCC-", 0],
+  ];
+  for (const [p, c, wl] of table) {
+    test(`(${p}, ${c}) -> ${wl}`, () => {
+      assert.equal(countryRatingChangeWl(p, c), wl);
+    });
+  }
+
+  test("all 361 pairs follow notchChange (>=2 -> 2, 1 -> 1, else 0)", () => {
+    let pairs = 0;
+    for (const p of RATING_SCALE) {
+      for (const c of RATING_SCALE) {
+        const n = notchChange(p, c);
+        const expected = n >= 2 ? 2 : n === 1 ? 1 : 0;
+        const actual = countryRatingChangeWl(p, c);
+        assert.equal(actual, expected, `${p} -> ${c}`);
+        assert.ok(Number.isInteger(actual) && actual >= 0 && actual <= 2, `${p} -> ${c}`);
+        pairs += 1;
+      }
+    }
+    assert.equal(pairs, 361);
+  });
+});
+
+describe("AC-3: input normalisation", () => {
+  test("case and surrounding whitespace are accepted", () => {
+    assert.equal(countryRatingChangeWl(" bbb+", "BBB\n"), 1);
+  });
+  test("BOM in front of the rating is accepted", () => {
+    assert.equal(countryRatingChangeWl(" bbb+", "﻿bb+"), 2);
+  });
+});
+
+describe("AC-4: invalid input throws RangeError", () => {
+  for (const [label, bad] of INVALID) {
+    test(`${label} as previous`, () => {
+      assert.throws(() => countryRatingChangeWl(bad, "BBB"), RangeError);
+    });
+    test(`${label} as current`, () => {
+      assert.throws(() => countryRatingChangeWl("BBB", bad), RangeError);
+    });
+  }
+
+  test("both invalid throws RangeError", () => {
+    assert.throws(() => countryRatingChangeWl("XYZ", "QQQ"), RangeError);
+  });
+
+  test("missing arguments throw RangeError", () => {
+    assert.throws(() => countryRatingChangeWl("BBB"), RangeError);
+    assert.throws(() => countryRatingChangeWl(), RangeError);
+  });
+
+  test("the error is not a TypeError", () => {
+    for (const [, bad] of INVALID) {
+      try {
+        countryRatingChangeWl(bad, "BBB");
+        assert.fail("expected throw");
+      } catch (e) {
+        assert.ok(e instanceof RangeError);
+        assert.ok(!(e instanceof TypeError));
+      }
+    }
+  });
+
+  test("previous is checked first", () => {
+    assert.throws(
+      () => countryRatingChangeWl("XYZ", "QQQ"),
+      (e) => e instanceof RangeError && e.message.includes("XYZ") && !e.message.includes("QQQ"),
+    );
+  });
+});
+
+describe("AC-8: intended difference to notchCalculator", () => {
+  test("C6: a 1-notch downgrade is wl 0 in notchCalculator but WL 1 in Indicator 12 (intended)", () => {
+    assert.equal(notchCalculator("BBB+", "BBB").wl, 0);
+    assert.equal(countryRatingChangeWl("BBB+", "BBB"), 1);
+  });
+});
+
+describe("AC-9: two parameters, no state", () => {
+  test("C7: length is 2", () => {
+    assert.equal(countryRatingChangeWl.length, 2);
+  });
+  test("C7: repeated calls do not influence each other", () => {
+    assert.equal(countryRatingChangeWl("BBB+", "BBB"), 1);
+    assert.equal(countryRatingChangeWl("BBB+", "BB+"), 2);
+    assert.equal(countryRatingChangeWl("BBB+", "BBB"), 1);
+  });
+  test("a third argument is ignored (no override)", () => {
+    assert.equal(countryRatingChangeWl("BBB+", "BBB", 0), 1);
+    assert.equal(countryRatingChangeWl("A", "A", 2), 0);
+  });
+});
+
+describe("AC-10 / AC-11: source and module shape", () => {
+  const source = readFileSync(SOURCE_URL, "utf8");
+
+  test("only static import is notchChange from ../ratings/notch.mjs", () => {
+    const imports = source.match(/^\s*import\b[^;]*;?/gm) ?? [];
+    assert.equal(imports.length, 1);
+    assert.match(imports[0], /import\s*\{\s*notchChange\s*\}\s*from\s*["']\.\.\/ratings\/notch\.mjs["']/);
+    assert.equal(/\bimport\s*\(/.test(source), false);
+    assert.equal(/\brequire\s*\(/.test(source), false);
+  });
+
+  test("no copy of the rating list", () => {
+    for (const literal of ['"BBB+"', "'BBB+'", '"CCC-"', "'CCC-'"]) {
+      assert.equal(source.includes(literal), false, literal);
+    }
+  });
+
+  test("no externalRatingChangeWl, node:, fs, http, console., process.", () => {
+    assert.equal(source.includes("externalRatingChangeWl"), false);
+    assert.equal(source.includes("node:"), false);
+    assert.equal(/["']fs["']|["']http["']/.test(source), false);
+    assert.equal(source.includes("console."), false);
+    assert.equal(source.includes("process."), false);
+  });
+
+  test("exports countryRatingChangeWl only (no externalRatingChangeWl, no default)", () => {
+    assert.equal(typeof indicatorModule.countryRatingChangeWl, "function");
+    assert.equal("externalRatingChangeWl" in indicatorModule, false);
+    assert.equal("default" in indicatorModule, false);
+  });
+
+  test("is synchronous", () => {
+    const result = countryRatingChangeWl("A", "A");
+    assert.equal(typeof result, "number");
+    assert.equal(result instanceof Promise, false);
+  });
+
+  test("package.json has no dependencies or devDependencies", () => {
+    const pkg = JSON.parse(readFileSync(PACKAGE_URL, "utf8"));
+    assert.equal("dependencies" in pkg, false);
+    assert.equal("devDependencies" in pkg, false);
+  });
+});
