+    assert.throws(() => countryRatingChangeWl(bad, "BBB"), RangeError);
+  });
+  test(`AC-4: ${label(bad)} as current (previous "BBB") throws RangeError`, () => {
+    assert.throws(() => countryRatingChangeWl("BBB", bad), RangeError);
+  });
+}
+
+test("AC-4: the argument left out throws RangeError (previous, current, both)", () => {
