+});
+
+test("AC-4: both invalid ('XYZ', 'QQQ') throws RangeError", () => {
+  assert.throws(() => countryRatingChangeWl("XYZ", "QQQ"), RangeError);
+});
+
+test("AC-4: non-strings throw RangeError, not TypeError", () => {
