+  assert.equal(countryRatingChangeWl.length, 2);
+});
+
+test("AC-9 / C7: no stored state - BBB+/BBB, then BBB+/BB+, then BBB+/BBB again gives 1, 2, 1", () => {
+  assert.equal(countryRatingChangeWl("BBB+", "BBB"), 1);
+  assert.equal(countryRatingChangeWl("BBB+", "BB+"), 2);
+  assert.equal(countryRatingChangeWl("BBB+", "BBB"), 1);
+});
+
+test("AC-9 / C7: a failed call does not poison later calls", () => {
+  assert.throws(() => countryRatingChangeWl("XYZ", "BBB"), RangeError);
+  assert.equal(countryRatingChangeWl("BBB+", "BBB-"), 2);
+});
+
+test("AC-9 / C7: no override - a third argument does not change the result", () => {
+  assert.equal(countryRatingChangeWl("BBB+", "BBB", 2), 1);
+  assert.equal(countryRatingChangeWl("BBB+", "BBB", { wl: 0 }), 1);
+  assert.equal(countryRatingChangeWl("BBB+", "BB+", 0), 2);
+});
+
+// ---------------------------------------------------------------- AC-10
+test("AC-10: the source has exactly one static import, notchChange from ../ratings/notch.mjs", () => {
+  const imports = [...SRC.matchAll(/^\s*import\b[^;]*;?/gm)].map((x) => x[0].trim());
+  assert.equal(imports.length, 1, imports.join("\n"));
+  assert.match(imports[0], /^import\s*\{\s*notchChange\s*\}\s*from\s*["']\.\.\/ratings\/notch\.mjs["']\s*;?$/);
+  assert.equal([...SRC.matchAll(/\bfrom\s*["']/g)].length, 1);
+});
+
+test("AC-10: the source has no quoted literal of the rating list ('BBB+' / 'CCC-')", () => {
+  for (const lit of ['"BBB+"', "'BBB+'", '"CCC-"', "'CCC-'", "`BBB+`", "`CCC-`"]) {
+    assert.ok(!SRC.includes(lit), `source contains ${lit}`);
+  }
+  assert.ok(!/\bRATING_SCALE\b/.test(SRC.replace(/\/\/.*$/gm, "")), "source defines or uses its own scale");
+});
+
+test("AC-10: the source uses notchChange for the calculation", () => {
+  assert.match(SRC, /notchChange\s*\(/);
+});
+
